/**
 * Measures one complete small binary document per invocation, including construction of a new writer. All eight-column
 * input rows and the reflective constructor lookup are prepared outside timing. The real byte-array sink is reused and
 * grown during setup.
 *
 * <p>
 * Results are nanoseconds per document and, with JMH's GC profiler, allocated bytes per document. There is deliberately
 * no operations-per-invocation normalization: a zero-row document is still one measured document.
 * </p>
 */
@State(Scope.Thread)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.NANOSECONDS)
@Warmup(iterations = 3, time = 1)
@Measurement(iterations = 5, time = 1)
@Fork(2)
public class SmallDocumentBenchmark {

	private static final String WRITER_PACKAGE = "org.eclipse.rdf4j.query.resultio.binary.";
	private static final String NS = "urn:small-document:";
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI CODE_DATATYPE = VF.createIRI(NS + "datatype:code");
	private static final List<String> NAMES = List.of("c0", "c1", "c2", "c3", "c4", "c5", "c6", "c7");

	@Param({ "published", "current" })
	public String implementation;

	@Param({ "0", "1", "8" })
	public int rows;

	/** The heartbeat sink uses the actual synchronized payload wrapper, without scheduling a heartbeat thread. */
	@Param({ "memory", "heartbeat" })
	public String sink;

	private Constructor<? extends TupleQueryResultWriter> constructor;
	private boolean heartbeatSink;
	private BindingSet[] bindings;
	private final ReusableOutput output = new ReusableOutput();

	@Setup(Level.Trial)
	public void setup() throws Exception {
		if (rows < 0) {
			throw new IllegalArgumentException("Negative row count: " + rows);
		}
		heartbeatSink = switch (sink) {
		case "memory" -> false;
		case "heartbeat" -> true;
		default -> throw new IllegalArgumentException("Unknown sink: " + sink);
		};
		String writerClass = switch (implementation) {
		case "published" -> WRITER_PACKAGE + "PublishedBinaryQueryResultWriter";
		case "current" -> WRITER_PACKAGE + "BinaryQueryResultWriter";
		default -> implementation.contains(".") ? implementation : WRITER_PACKAGE + implementation;
		};
		constructor = Class.forName(writerClass).asSubclass(TupleQueryResultWriter.class).getConstructor(OutputStream.class);
		bindings = new BindingSet[rows];
		for (int row = 0; row < rows; row++) {
			Value[] values = new Value[] {
					VF.createIRI(NS + "subject:" + row + "-0"),
					VF.createLiteral("sample-label-" + row + "-1"),
					VF.createLiteral(Integer.toString(row * 31 + 2), CoreDatatype.XSD.INTEGER),
					VF.createLiteral("sample-label-" + row + "-3", "en"),
					VF.createBNode("node-" + row + "-4"),
					VF.createIRI(NS + "kind:" + row % 17 + "-5"),
					VF.createLiteral(row + ".125", CoreDatatype.XSD.DECIMAL),
					VF.createLiteral("sample-label-" + row + "-7", CODE_DATATYPE)
			};
			bindings[row] = new ListBindingSet(NAMES, values);
		}
		// Pre-grow the actual output buffer and initialize lazy fixture fields before measurement.
		writeDocument();
	}

	@Benchmark
	public int serialize(Blackhole blackhole) throws Exception {
		writeDocument();
		blackhole.consume(output.backingArray());
		blackhole.consume(output.sample());
		return output.size();
	}

	private void writeDocument() throws Exception {
		output.reset();
		QueryResponseHeartbeat heartbeat = heartbeatSink ? new QueryResponseHeartbeat(output, () -> {
			throw new AssertionError("The in-memory benchmark sink cannot disconnect");
		}) : null;
		OutputStream target = heartbeat == null ? output : heartbeat.getOutputStream();
		// Resolve the constructor once per trial; invoke it once per complete document.
		TupleQueryResultWriter writer = constructor.newInstance(target);
		if (heartbeat != null && heartbeat.start(writer)) {
			heartbeat.close();
			throw new AssertionError("Binary writers must not schedule whitespace heartbeats");
		}
		writer.startQueryResult(NAMES);
		for (BindingSet row : bindings) {
			writer.handleSolution(row);
		}
		writer.endQueryResult();
		if (heartbeat != null) {
			heartbeat.complete();
		}
	}

	/** Parse the complete output and compare every row and term, outside the measured operation. */
	public void validateOutput() throws Exception {
		QueryResultCollector collector = new QueryResultCollector();
		BinaryQueryResultParser parser = new BinaryQueryResultParser();
		parser.setQueryResultHandler(collector);
		parser.parseQueryResult(new ByteArrayInputStream(output.backingArray(), 0, output.size()));
		List<BindingSet> parsed = collector.getBindingSets();
		if (parsed.size() != rows || !collector.getBindingNames().equals(NAMES)) {
			throw new AssertionError("Invalid output dimensions: " + parsed.size() + " rows, "
					+ collector.getBindingNames());
		}
		for (int row = 0; row < rows; row++) {
			if (!bindings[row].equals(parsed.get(row))) {
				throw new AssertionError("Round-trip mismatch at row " + row + ": expected " + bindings[row]
						+ ", got " + parsed.get(row));
			}
		}
	}

	/**
	 * Smoke validation; optional CSV arguments select implementations, row counts, and sinks, respectively. Every output
	 * is parsed and compared term by term. For each row count, output bytes must also equal the first selected
	 * implementation/sink's bytes.
	 */
	public static void main(String[] args) throws Exception {
		String[] implementations = args.length > 0 ? args[0].split(",") : new String[] { "published", "current" };
		int[] rowCounts = args.length > 1 ? Arrays.stream(args[1].split(",")).mapToInt(Integer::parseInt).toArray()
				: new int[] { 0, 1, 8 };
		String[] sinks = args.length > 2 ? args[2].split(",") : new String[] { "memory", "heartbeat" };
		Map<Integer, byte[]> references = new HashMap<>();
		for (String implementation : implementations) {
			for (int rows : rowCounts) {
				for (String sink : sinks) {
					SmallDocumentBenchmark benchmark = new SmallDocumentBenchmark();
					benchmark.implementation = implementation;
					benchmark.rows = rows;
					benchmark.sink = sink;
					benchmark.setup();
					benchmark.validateOutput();
					byte[] bytes = benchmark.output.toByteArray();
					byte[] reference = references.putIfAbsent(rows, bytes);
					if (reference != null && !Arrays.equals(reference, bytes)) {
						throw new AssertionError("Wire-byte mismatch: " + implementation + "," + sink + ",rows="
								+ rows);
					}
					System.out.println(implementation + "," + sink + ",rows=" + rows + ",bytes=" + bytes.length
							+ ",roundtrip=PASS,wirematch=" + (reference == null ? "REFERENCE" : "PASS"));
				}
			}
		}
	}

	private static final class ReusableOutput extends ByteArrayOutputStream {
		byte[] backingArray() {
			return buf;
		}

		int sample() {
			return count == 0 ? 0 : (buf[count / 4] & 0xff) ^ (buf[count / 2] & 0xff) << 8
					^ (buf[count * 3 / 4] & 0xff) << 16 ^ (buf[count - 1] & 0xff) << 24;
		}
	}
}
